import attr
from typing import List, Any, Optional

from .connection_details import SshServiceDetails


@attr.s(cmp=False)
class Connection(object):
    """Connection between device where is defined and other device.

    :param str interface: Source interface e.g. eth0.
    :param str interface_type: Source interface type e.g. lmp.
    :param Any device: Destination device e.g. gNB, eNB.
    """
    interface = attr.ib(type=str)
    interface_type = attr.ib(type=Optional[str])
    device = attr.ib(type=Any)


@attr.s(cmp=False)
class TestPc(object):
    """Virtual machine or a physical host on which tests are run.
    Host username and password will point to a user belonging to sudoers.
    By default it will be base on UTE debian-x template


    :param SshServiceDetails default_ssh_connection_details: SshServiceDetails class instance object
    :param List connections: a list of Connections or components that are connected to the TestPC
    """
    default_ssh_connection_details = attr.ib(type=SshServiceDetails)
    connections = attr.ib(default=attr.Factory(list), type=Optional[List[Any]])
